contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address to, uint256 amount) public {
        require(to != address(this), "recipient must be test contract");

        uint256 beforeSender = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 beforeRecipient = c.balanceOf(to); if (__ESBMC_reverted()) return;

        c.transfer(to, amount); if (__ESBMC_reverted()) return;

        uint256 afterSender = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 afterRecipient = c.balanceOf(to); if (__ESBMC_reverted()) return;

        assert(afterSender + afterRecipient == beforeSender + beforeRecipient);
    }
}

